script:
(function () {
  'use strict';
  // Buy a home, hold it, sell it: value, equity, sale proceeds and the cost of owning it.
  //   Value after y years: V(y) = P * (1 + g)^y (annual appreciation g, may be negative).
  //   Loan balance after m payments: B = L(1+i)^m - M((1+i)^m - 1)/i, i = rate/12 (L - M*m at 0%),
  //   with M = L * i / (1 - (1 + i)^-n).
  //   Net proceeds if sold in year y = V(y) * (1 - selling cost %) - B(12y).
  //   Gain over your money = net proceeds - (down payment + buying costs + principal repaid)
  //                        = appreciation - buying costs - selling costs.
  //   Ownership costs in year y: property tax and maintenance as a % of the value at the start of
  //   the year; insurance and HOA dues flat.
  // Verified in Node (scratchpad tests/w3re): $400,000 at 3% for 10 yrs = $537,566.55 (closed form);
  //   balance on $320,000 at 6.5% for 30 yrs after 120 payments = $271,283.60, equal to the closed
  //   form above and a month-by-month loop; gain identity (appreciation - buying - selling costs)
  //   holds to the cent; 0% appreciation never breaks even; 0% rate and negative appreciation
  //   work; a hold longer than the loan term leaves a $0 balance; no NaN/Infinity on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(loan, i, n) {
    if (loan <= 0 || n <= 0) return 0;
    if (i === 0) return loan / n;
    return loan * i / (1 - Math.pow(1 + i, -n));
  }

  // Month-by-month so the interest paid each year is exact; returns per-year totals.
  function loanByYear(loan, i, n, years) {
    var pay = payment(loan, i, n), bal = loan, out = [];
    for (var y = 1; y <= years; y++) {
      var interest = 0, principal = 0;
      for (var k = 1; k <= 12; k++) {
        var m = (y - 1) * 12 + k;
        if (m > n || bal <= 0) break;
        var mi = bal * i;
        var pr = m === n ? bal : Math.min(pay - mi, bal);
        bal -= pr;
        if (bal < 0.005) bal = 0;
        interest += mi; principal += pr;
      }
      out.push({ interest: interest, principal: principal, balance: bal });
    }
    return { pay: pay, years: out };
  }

  function duration(y) { return y + (y === 1 ? ' year' : ' years'); }

  function clearResults() {
    ['reNet', 'reValueOut', 'reBalanceOut', 'reEquityOut', 'rePI', 'reCashIn', 'rePrincipal', 'reAppreciation', 'reSellCosts',
     'reGain', 'reInterest', 'reTaxTotal', 'reInsTotal', 'reMaintTotal', 'reHoaTotal', 'reTxnTotal', 'reCostTotal', 'reCostMonthly']
      .forEach(function (id) { setText(id, '–'); });
    setText('reBreakEven', '–');
    el('reSchedule').innerHTML = '';
  }

  function update() {
    var price = read('rePrice'), down = read('reDown', true), downUnit = el('reDownUnit').value,
        rate = read('reRate'), term = read('reTerm'), buyPct = read('reBuyCost', true), growth = read('reGrowth', true),
        years = read('reYears'), sellPct = read('reSellCost', true),
        tax = read('reTax', true), ins = read('reIns', true), maint = read('reMaint', true), hoa = read('reHoa', true);
    var downAmt = downUnit === 'percent' ? price * down / 100 : down;
    var msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a purchase price greater than $0.';
    else if (isNaN(down) || down < 0 || downAmt > price) msg = 'Enter a down payment from 0 up to the purchase price.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(term) || term < 1 || term > 50 || term % 1 !== 0) msg = 'Enter a loan term of 1 to 50 whole years.';
    else if (isNaN(years) || years < 1 || years > 50 || years % 1 !== 0) msg = 'Enter how long you keep the home: 1 to 50 whole years.';
    else if (isNaN(growth) || growth < -20 || growth > 20) msg = 'Enter a yearly change in value from -20% to 20%.';
    else if ([buyPct, sellPct, tax, ins, maint, hoa].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Costs cannot be negative.';
    else if (buyPct > 15 || sellPct > 15) msg = 'Enter buying and selling costs of 15% or less.';
    else if (tax > 10 || maint > 10) msg = 'Enter property tax and maintenance of 10% of the value or less.';
    var error = el('reError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var loan = price - downAmt, g = growth / 100, i = rate / 1200, n = term * 12;
    var ln = loanByYear(loan, i, n, years);
    var buyCost = price * buyPct / 100;
    var cashIn = downAmt + buyCost;
    var rows = [], principalPaid = 0, totals = { interest: 0, tax: 0, ins: 0, maint: 0, hoa: 0 }, breakEven = 0;
    for (var y = 1; y <= years; y++) {
      var startValue = price * Math.pow(1 + g, y - 1), value = price * Math.pow(1 + g, y);
      var ly = ln.years[y - 1];
      principalPaid += ly.principal;
      totals.interest += ly.interest;
      totals.tax += startValue * tax / 100;
      totals.maint += startValue * maint / 100;
      totals.ins += ins;
      totals.hoa += hoa * 12;
      var net = value * (1 - sellPct / 100) - ly.balance;
      var gain = net - cashIn - principalPaid;
      if (!breakEven && gain >= 0) breakEven = y;
      rows.push({ year: y, value: value, balance: ly.balance, equity: value - ly.balance, net: net, gain: gain });
    }
    var last = rows[rows.length - 1];
    var sellCost = last.value * sellPct / 100;
    var txn = buyCost + sellCost;
    var costTotal = totals.interest + totals.tax + totals.ins + totals.maint + totals.hoa + txn;

    setText('reNet', money0.format(last.net));
    setText('reValueOut', money0.format(last.value));
    setText('reBalanceOut', money0.format(last.balance));
    setText('reEquityOut', money0.format(last.equity));
    setText('rePI', money.format(ln.pay));
    setText('reCashIn', money.format(cashIn));
    setText('rePrincipal', money.format(principalPaid));
    setText('reAppreciation', money.format(last.value - price));
    setText('reSellCosts', money.format(sellCost));
    setText('reGain', money.format(last.gain));
    setText('reInterest', money.format(totals.interest));
    setText('reTaxTotal', money.format(totals.tax));
    setText('reInsTotal', money.format(totals.ins));
    setText('reMaintTotal', money.format(totals.maint));
    setText('reHoaTotal', money.format(totals.hoa));
    setText('reTxnTotal', money.format(txn));
    setText('reCostTotal', money.format(costTotal));
    setText('reCostMonthly', money.format(costTotal / (years * 12)));
    setText('reBreakEven', breakEven
      ? 'After ' + duration(breakEven) + ', the home’s rise in value covers your buying and selling costs, so selling would return at least the down payment, buying costs and principal you put in.'
      : 'Within ' + duration(years) + ', the home’s rise in value does not cover your buying and selling costs, so selling would return less than the down payment, buying costs and principal you put in.');

    el('reSchedule').innerHTML = rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money0.format(row.value) + '</td><td>' + money0.format(row.balance) + '</td><td>' +
        money0.format(row.equity) + '</td><td>' + money0.format(row.net) + '</td><td>' + money0.format(row.gain) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('reForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
